import physics3d
main=()=>{
    let world=physics3d.World[gravity=vec3(0 -18 0)]
    world.add_box(vec3(0 -0.5 0) vec3(40 1 40) kind=physics3d.BodyKind.fixed)
    world.add_box(vec3(0 1.5 -20) vec3(40 3 1) kind=physics3d.BodyKind.fixed)
    world.add_box(vec3(0 1.5 20) vec3(40 3 1) kind=physics3d.BodyKind.fixed)
    world.add_box(vec3(-20 1.5 0) vec3(1 3 40) kind=physics3d.BodyKind.fixed)
    world.add_box(vec3(20 1.5 0) vec3(1 3 40) kind=physics3d.BodyKind.fixed)
    let crates:array<physics3d.Body>=[]
    seed_random(3)
    loop i in [0..18) {
        let size=random(1.2 2.8)
        let center=vec3(random(-16.0 16.0) size/2.0 random(-16.0 16.0))
        if length(vec2(center.x center.z)-vec2(0 8))<?3.0 continue
        crates.push(world.add_box(center vec3(size size size) density=150))
    }
    let player=world.character(vec3(0 0 8) radius=0.35)
    let before=time_ns()
    loop frame in [0..600) {
        if frame%60=?0 {
            let body=crates[(frame//60)%crates.length]
            world.push(body vec3(400 500 0) world.pos(body))
        }
        let direction=if frame%240<?120 1.0 else -1.0
        let jump=if frame%120=?0 6.5 else 0.0
        world.walk(@player vec3(direction 0 0) 1.0/60.0 jump=jump)
        world.step(1.0/60.0)
    }
    let elapsed=time_ns()-before
    let sum=0.0
    loop body in crates sum+=float64(world.pos(body).x+world.pos(body).y+world.pos(body).z)
    printl"{elapsed} {sum} {player.feet}"
}
